def retire_generated_content(apps,schema_editor):
    from django.utils.html import escape
    Article=apps.get_model('news','Article')
    # Only the explicitly generated sample records are removed; real articles remain.
    Article.objects.filter(demo=True).delete()
    for item in Article.objects.all().iterator():
        paragraphs=['<p>'+escape(part).replace('\n','<br>')+'</p>' for part in item.body.split('\n\n') if part.strip()]
        Article.objects.filter(pk=item.pk).update(body=''.join(paragraphs))
    Author=apps.get_model('news','Author')
    Author.objects.filter(slug='cedarmond-desk',article__isnull=True,bio__contains='sample articles').delete()
    Tag=apps.get_model('news','Tag')
    Tag.objects.filter(slug='the-big-picture',article__isnull=True).delete()

